/* ===== ☯ HIỆU ỨNG ĐẠO THỂ (world/46-dao-the-fx.js) =====
 * Khi nhân vật đã Hợp Đạo (Đạo Thể: HDAO.on(), Đạo Cảnh Lv1 trở lên):
 *   - TẤT CẢ hiệu ứng cảnh giới tu tiên quanh nhân vật (cột sáng, cánh, vòng trận mặt đất, Kim Đan, Nguyên Anh, Hóa Thần...) bị ẩn.
 *   - CHỈ giữ lại hiệu ứng của Luyện Hư (vầng sáng HQI xoay ở ngực, vẽ giống hệt engine).
 *   - THÊM hiệu ứng Đạo Thể: trận đồ Bát Quái – Thái Cực vàng (ảnh nhúng bên dưới) dưới chân + ánh vàng sau lưng + tinh quang bay lên.
 * Cách làm: bọc ZC.aura() (engine gọi ZC.aura() ngay trước hero(); Đấu Trường cũng gọi). Không sửa engine, không đổi dữ liệu/save.
 * Nhân vật chưa hợp đạo: gọi nguyên bản ZC.aura() → hiệu ứng tu tiên giữ nguyên.
 * Chỉnh kích thước/độ sáng: khối CF. Ở mức hiệu năng "Tiết kiệm" (window.QL>=2) bỏ tinh quang + lớp nhấp nháy cho nhẹ máy. */
(function(){
'use strict';
if(typeof ZC==='undefined'||typeof ZC.aura!=='function')return;
var CF={w:340,flat:.62,alpha:.82,glow:.16,motes:7};
var IMG=new Image();IMG.src='data:image/webp;base64,';
var PI=Math.PI;
function isDT(){try{return !!(window.HDAO&&window.HDAO.on&&window.HDAO.on())}catch(e){return false}}
function star(x,y,z){g.beginPath();g.moveTo(x,y-z*2);g.lineTo(x+z*.5,y);g.lineTo(x,y+z*2);g.lineTo(x-z*.5,y);g.fill();g.beginPath();g.moveTo(x-z*2,y);g.lineTo(x,y+z*.5);g.lineTo(x+z*2,y);g.lineTo(x,y-z*.5);g.fill()}

/* Hiệu ứng Luyện Hư: sao chép đúng khối `else if(k>=5)` của ZC.aura trong engine (vầng sáng HQI xoay chậm, ánh 'lighter') */
function luyenHu(x,gy,t){
 if(typeof HQI==='undefined'||!HQI.complete||!HQI.naturalWidth)return;
 var d=(100+14)*s*(1+Math.sin(t*.06)*.025);
 g.save();g.translate(x,gy-66*s);g.rotate(t*.004);g.globalCompositeOperation='lighter';g.globalAlpha=.9+Math.sin(t*.07)*.08;g.drawImage(HQI,-d/2,-d/2,d,d);g.restore()}

/* Hiệu ứng Đạo Thể: trận đồ Bát Quái vàng dưới chân + ánh vàng + tinh quang */
function formation(x,gy,t){
 var lite=(window.QL|0)>=2;
 /* ánh vàng nhẹ sau lưng (luôn vẽ, rất rẻ) */
 var by=gy-72*s,r=105*s,q=g.createRadialGradient(x,by,r*.08,x,by,r);
 q.addColorStop(0,'rgba(255,226,120,.9)');q.addColorStop(.5,'rgba(255,170,40,.35)');q.addColorStop(1,'rgba(255,150,20,0)');
 g.save();g.globalCompositeOperation='lighter';g.globalAlpha=CF.glow+Math.sin(t*.045)*.04;g.fillStyle=q;g.beginPath();g.arc(x,by,r,0,PI*2);g.fill();g.restore();
 if(!IMG.complete||!IMG.naturalWidth)return;
 var ar=IMG.naturalHeight/IMG.naturalWidth,w=CF.w*s*(1+Math.sin(t*.035)*.03),h=w*ar*CF.flat,cy=gy-6*s;
 g.save();g.globalCompositeOperation='lighter';
 g.globalAlpha=CF.alpha+Math.sin(t*.05)*.1;g.drawImage(IMG,x-w/2,cy-h/2,w,h);
 if(!lite){   /* lớp thứ 2 mờ, xoay lắc nhẹ → trận đồ như đang chuyển động */
  g.globalAlpha=.24+Math.sin(t*.045+1.3)*.1;g.translate(x,cy);g.rotate(Math.sin(t*.012)*.035);g.scale(1.05,1.05);g.drawImage(IMG,-w/2,-h/2,w,h)}
 g.restore();
 if(!lite){   /* tinh quang vàng bay lên từ trận đồ */
  g.save();g.globalCompositeOperation='lighter';g.fillStyle='#ffe9a0';
  for(var i=0;i<CF.motes;i++){var ph=(t*.012+i/CF.motes)%1,X=x+Math.sin(i*2.4+t*.004)*w*.36,Y=gy-(8+ph*170)*s,z=(1.2+Math.sin(ph*PI)*2.6)*s;g.globalAlpha=Math.sin(ph*PI)*.85;star(X,Y,z)}
  g.restore()}
}

var _aura=ZC.aura;
ZC.aura=function(){
 if(!isDT())return _aura.apply(this,arguments);   /* chưa hợp đạo: hiệu ứng tu tiên nguyên bản */
 if(vil)return;
 var x=(P.x-cam)*s,gy=GY,t=fr;
 g.save();try{formation(x,gy,t);luyenHu(x,gy,t)}catch(e){}finally{g.restore()}};

window.DTFX={cfg:CF,isDT:isDT};
})();
